//! Rendering. Pure — it takes the manifest values and the overlay TEXT, so the
//! shape of the output is testable without touching a filesystem.

use gates_config::Config;
use std::path::{Path, PathBuf};

/// The banner every rendered file carries. Present so a human editing the file
/// directly learns, in the file itself, that their edit will be overwritten.
pub const BANNER: &str =
    "<!-- Generated by render-agent-docs. Edit the manifest or the overlay, not this file. -->";

/// Codex's default `project_doc_max_bytes`.
pub const DEFAULT_MAX_BYTES: usize = 32_768;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Target {
    pub name: String,
    pub path: String,
    pub title: String,
    /// Size ceiling for the rendered file; 0 means none.
    ///
    /// Codex applies `project_doc_max_bytes` to the whole root-to-cwd chain of
    /// AGENTS.md files, so a per-file check is a floor, not the full check.
    pub max_bytes: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Manifest {
    /// Rule fragment names, in the order they should load.
    pub rules: Vec<String>,
    /// Directory containing Markdown rule fragments to embed.
    pub rules_dir: String,
    /// Path to the repo-specific body, appended after the rules block.
    pub overlay: Option<String>,
    pub targets: Vec<Target>,
}

impl Manifest {
    /// The manifest, or the key that holds an unusable value.
    pub fn from_config(cfg: &Config) -> Result<Manifest, String> {
        let mut targets = Vec::new();
        for name in cfg.tables_under("targets") {
            let Some(path) = cfg.string(&format!("targets.{name}.path")) else {
                continue;
            };
            let title = cfg
                .string(&format!("targets.{name}.title"))
                .unwrap_or(path)
                .to_string();
            let key = format!("targets.{name}.max_bytes");
            let max_bytes = match cfg.string(&key) {
                None => DEFAULT_MAX_BYTES,
                Some(raw) => raw
                    .trim()
                    .parse()
                    .map_err(|_| format!("{key} = \"{raw}\" is not a whole number of bytes"))?,
            };
            targets.push(Target {
                name,
                path: path.to_string(),
                title,
                max_bytes,
            });
        }
        Ok(Manifest {
            rules: cfg.list("rules").unwrap_or_default(),
            rules_dir: cfg
                .string("rules_dir")
                .unwrap_or("rules")
                .trim_end_matches('/')
                .to_string(),
            overlay: cfg.string("overlay").map(str::to_string),
            targets,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rule {
    pub name: String,
    pub text: String,
}

pub fn load_rules(manifest: &Manifest) -> Result<Vec<Rule>, String> {
    let base = expand_home(&manifest.rules_dir);
    manifest
        .rules
        .iter()
        .map(|name| {
            let path = base.join(format!("{name}.md"));
            let text =
                std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
            Ok(Rule {
                name: name.clone(),
                text,
            })
        })
        .collect()
}

pub fn expand_home(path: &str) -> PathBuf {
    let Some(rest) = path.strip_prefix("~/") else {
        return PathBuf::from(path);
    };
    std::env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_default()
        .join(rest)
}

/// Whether `codex-guard rule-scope` reads rules from `rules_dir`: a directory
/// ending in `.agents/rules` or `.claude/rules`, or `<codex_home>/agent-rules`.
/// Only then may a path-scoped rule be left out of AGENTS.md.
pub fn rule_scope_reads(rules_dir: &Path, codex_home: Option<&Path>) -> bool {
    let parent = rules_dir.parent().and_then(Path::file_name);
    let in_repo = rules_dir.file_name().is_some_and(|n| n == "rules")
        && parent.is_some_and(|p| p == ".agents" || p == ".claude");
    let global = codex_home.is_some_and(|home| rules_dir == home.join("agent-rules"));
    in_repo || global
}

/// The full text of one target file.
///
/// Whole-file generation is deliberate. A "managed region" between markers
/// leaves the rest hand-written, and the hand-written rest is exactly where the
/// two files drift apart. Anything a repo needs to say for itself goes in the
/// overlay, which both targets share.
///
/// With `defer_scoped`, a rule whose frontmatter declares `paths:` is not
/// inlined: it is named in one line, and `codex-guard rule-scope` delivers it
/// when a call touches a matching file. Without it, every rule is inlined.
pub fn render(
    target: &Target,
    overlay: Option<&str>,
    rules: &[Rule],
    defer_scoped: bool,
) -> String {
    let mut out = String::new();
    out.push_str(&format!("# {}\n\n", target.title));
    out.push_str(BANNER);
    out.push_str("\n\n");

    if !rules.is_empty() {
        out.push_str("## Rules\n\n");
        out.push_str("Generated from portable fragments; edit source rules and re-render.\n\n");
        let mut scoped: Vec<&str> = Vec::new();
        for rule in rules {
            if defer_scoped && is_path_scoped(&rule.text) {
                scoped.push(&rule.name);
                continue;
            }
            out.push_str(&format!("### {}\n\n", rule.name));
            out.push_str(rule_body(&rule.text));
            out.push_str("\n\n");
        }
        if !scoped.is_empty() {
            out.push_str(&format!(
                "Path-scoped, loaded by `codex-guard rule-scope` when a call touches a matching file: {}.\n\n",
                scoped.join(", ")
            ));
        }
    }

    if let Some(body) = overlay {
        let body = body.trim_start_matches('\u{feff}').trim();
        if !body.is_empty() {
            out.push_str(body);
            out.push('\n');
        }
    }
    out
}

/// Why a rendered target breaks its cap, or `None` when it fits.
pub fn over_cap(target: &Target, rendered: &str) -> Option<String> {
    let size = rendered.len();
    if target.max_bytes == 0 || size <= target.max_bytes {
        return None;
    }
    Some(format!(
        "{} (target {}) is {size} bytes, over its max_bytes of {}. Codex cuts the project \
         AGENTS.md chain at project_doc_max_bytes with only a log warning, so the text past \
         the cut never reaches the model. Give file-type rules `paths:` frontmatter in a \
         directory `codex-guard rule-scope` reads (.agents/rules, .claude/rules), trim the \
         overlay, or raise the cap together with project_doc_max_bytes.",
        target.path, target.name, target.max_bytes
    ))
}

/// The YAML frontmatter a rule opens with, if it opens with one.
fn frontmatter(text: &str) -> Option<(&str, &str)> {
    let text = text.trim_start_matches('\u{feff}');
    let rest = text.strip_prefix("---")?;
    let rest = rest
        .strip_prefix("\r\n")
        .or_else(|| rest.strip_prefix('\n'))?;
    let mut offset = 0;
    for line in rest.split_inclusive('\n') {
        if line.trim_end() == "---" {
            return Some((&rest[..offset], &rest[offset + line.len()..]));
        }
        offset += line.len();
    }
    None
}

pub fn is_path_scoped(text: &str) -> bool {
    frontmatter(text).is_some_and(|(front, _)| front.lines().any(|l| l.starts_with("paths:")))
}

fn rule_body(text: &str) -> &str {
    let text = frontmatter(text).map_or(text, |(_, body)| body);
    let text = text.trim_start_matches('\u{feff}').trim();
    if !text.starts_with("# ") {
        return text;
    }
    text.split_once('\n')
        .map(|(_, body)| body.trim_start())
        .unwrap_or("")
}

